+        new AnonymousConsentsActions.LoadAnonymousConsentTemplatesSuccess(
+          mockConsentTemplates
+        )
+      );
+
+      let result = false;
+      store
+        .pipe(
+          select(AnonymousConsentsSelectors.getAnonymousConsentTemplatesSuccess)
+        )
+        .subscribe(value => (result = value))
