+        'toggleAnonymousConsentsBannerVisibility'
+      ).and.stub();
+      component.hideBanner();
+      expect(
+        anonymousConsentsService.toggleAnonymousConsentsBannerVisibility
+      ).toHaveBeenCalledWith(false);
+    });
+  });
