+  describe('ngOnDestroy', () => {
+    it('should unsubscribe', () => {
+      spyOn<any>(component['subscriptions'], 'unsubscribe').and.stub();
+      component.ngOnDestroy();
+      expect(component['subscriptions'].unsubscribe).toHaveBeenCalled();
+    });
