+// @import '../../theme';
+
+%cx-anonymous-consent-form {
+  /* Checkboxes should work without toggle button styling
+Reset visible focus color to single color*/
+
+  //Global Stuff
+
+  cx-icon {
+    position: absolute;
+    top: 15px;
+    left: 15px;
+    color: var(--cx-color-secondary);
+
+    &:before {
+      font-size: 1.6rem;
+    }
+  }
+
+  .cx-keyb-focusable:focus > .cx-keyb-visualfocus,
+  .cx-keyb-focusable:focus ~ .cx-keyb-visualfocus {
+    box-shadow: 0 0 2px 2px var(--cx-color-visual-focus);
+  }
+  .cx-keyb-focusable:focus,
+  .cx-keyb-visualfocus:focus {
+    outline: none;
+  }
+
+  //-----------------------------------------------------
+
+  //Accordion
+  .cx-accordion {
+    margin: 5px auto;
+    line-height: 1.6;
+    list-style-type: none;
+    padding: 0;
+    //this below is custom not global
+    @include media-breakpoint-down(xs) {
+      margin: 0;
+    }
+  }
+  .cx-accordion-item {
+    border: 1px solid var(--cx-color-light);
+    position: relative;
+    margin-top: 10px;
+    margin-bottom: 10px;
+    //this below is custom not global
+    @include media-breakpoint-down(xs) {
+      margin: 0;
+      border-bottom: 0 none;
+    }
+  }
+  .cx-accordion-title {
+    padding: 15px 15px 15px 50px;
+    display: block;
+    position: relative;
+    font-weight: 600;
+    //this below is custom not global
+    @include media-breakpoint-down(xs) {
+      width: 60%;
+    }
+  }
+  .cx-accordion-tab {
+    background-color: var(--cx-color-inverse);
+  }
+  .cx-accordion-tab:hover {
+    cursor: pointer;
+  }
+  .cx-accordion-content {
+    padding: 0 40px 10px 40px;
+  }
+  .cx-accordion-tabpanel {
+    transition: height 0.3s ease-out;
+    height: 0;
+    overflow: hidden;
+    background-color: var(--cx-color-inverse);
+  }
+
+  //-----------------------------------------------------
+  // Move all this to cxbase except for positioning
+  //Toggle Button
+  .cx-toggle-button {
+    position: absolute;
+    top: 10px;
+    left: 100%;
+    @include media-breakpoint-down(xs) {
+      margin-left: -33%;
+    }
+    @include media-breakpoint-up(sm) {
+      margin-left: -16%;
+    }
+    @include media-breakpoint-up(md) {
+      margin-left: -15%;
+    }
+    @include media-breakpoint-up(lg) {
+      margin-left: -14%;
+    }
+  }
+  .cx-toggle-button *,
+  .cx-toggle-button *:before,
+  .cx-toggle-button *:after {
+    box-sizing: border-box;
+  }
+  //Checkbox Control
+  .cx-toggle-button input[type='checkbox'] {
+    opacity: 0;
+    position: absolute;
+    top: 0;
+    left: 0;
+  }
+
+  //----- Checkbox Control - Checked
+  .cx-toggle-button input[type='checkbox']:checked ~ label .cx-toggle-switch {
+    background-color: var(--cx-color-primary);
+    border: 1px solid var(--cx-color-primary);
+  }
+  .cx-toggle-button
+    input[type='checkbox']:checked
+    ~ label
+    .cx-toggle-switch:before {
+    content: '\00a0';
+    left: 0;
+  }
+  .cx-toggle-button
+    input[type='checkbox']:checked
+    ~ label
+    .cx-toggle-switch:after {
+    content: '\00a0';
+    border: 2px solid var(--cx-color-inverse);
+    background-color: var(--cx-color-inverse);
+    transform: translate3d(22px, 0, 0);
+  }
+
+  //----- Checkbox Control - Disabled
+  .cx-toggle-button input[type='checkbox'][disabled] ~ label,
+  .cx-toggle-button input[type='checkbox'][disabled] ~ label .cx-toggle-switch {
+    pointer-events: none;
+  }
+
+  //----- Checkbox Control - Checked and Disabled
+  .cx-toggle-button
+    input[type='checkbox'][disabled]:checked
+    ~ label
+    .cx-toggle-switch {
+    background-color: var(--cx-color-light);
+    border: 1px solid var(--cx-color-light);
+  }
+
+  .cx-toggle-button
+    input[type='checkbox'][disabled]:checked
+    ~ label
+    .cx-toggle-text {
+    color: var(--cx-color-light);
+  }
+
+  //Toggle Switch
+  .cx-toggle-button label {
+    user-select: none;
+    position: relative;
+    display: flex;
+    align-items: center;
+  }
+  .cx-toggle-button label .cx-toggle-switch {
+    position: relative;
+    height: 32px;
+    flex: 0 0 56px;
+    border-radius: 60px;
+    border: 1px solid var(--cx-color-secondary);
+    background-color: var(--cx-color-inverse);
+    transition: background-color 0.3s cubic-bezier(0, 1, 0.5, 1);
